#!/bin/sh
# Regenerate the C binding of every Omega unit linked into the hosted CUDA++ build (UNITS below), or
# with --check confirm the committed files are exactly what the pinned tools produce (exit 1 on any
# difference, 3 NOT_RUN without the tools). Same pattern and pins as aien-dev/omega-mv om/units.sh.
#   OMEGA_OMC     seed-born omc (aien-dev/omega-mv seed/out/omc), sha256 pinned below
#   OMEGA_BRIDGE  an aien-dev/omega-bridge checkout at om/omega-bridge.lock; src/native.om sha256 pinned below
# Generated by the bridge's src/native.om (omega-bridge docs/NATIVE-ABI.md, ABI v1, OM-1 units):
#   src/cudapp_om_units.c      every unit's machine code, byte for byte as omc wrote it, and its binding
#   src/cudapp_native.h        the bindings' declarations
#   src/cudapp_om_units.ident  each unit's identity: source sha256, compiler pin, ABI, profile
# A unit or compiler that changes without regenerating these files fails --check (make test-om-units).
set -eu
OMC_PIN=2c82480596bbdc50cda9626866209ef662d5834f278f839ff4ce0250c495029f
NATIVE_PIN=c77a5922f91d53d4a0bbd4e7b1c4703f7098263abc843be2918db1ece7496782
ROOT=$(cd "$(dirname "$0")/.." && pwd)
UNITS="${OMEGA_UNITS:-om/encoder/bw_enc_sm121.om om/cubin/cubin_elf.om}"
OUTS="cudapp_om_units.c cudapp_native.h cudapp_om_units.ident"
DEST="${OMEGA_UNITS_DEST:-$ROOT/src}"
[ -n "${OMEGA_OMC:-}" ] && [ -n "${OMEGA_BRIDGE:-}" ] || { echo "NOT_RUN: set OMEGA_OMC and OMEGA_BRIDGE"; exit 3; }
[ "$(sha256sum < "$OMEGA_OMC" | cut -c1-64)" = "$OMC_PIN" ] || { echo "NOT_RUN: omc is not the pinned compiler"; exit 3; }
[ "$(sha256sum < "$OMEGA_BRIDGE/src/native.om" | cut -c1-64)" = "$NATIVE_PIN" ] || { echo "NOT_RUN: native.om is not the pinned generator"; exit 3; }
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
"$OMEGA_OMC" < "$OMEGA_BRIDGE/src/native.om" > "$T/native"; chmod +x "$T/native"
: > "$T/units.in"; : > "$T/cudapp_om_units.ident"
for u in $UNITS; do
  case "$u" in /*) src=$u ;; *) src=$ROOT/$u ;; esac
  name=$(basename "$u" .om | tr -c 'A-Za-z0-9_\n' '_')
  "$OMEGA_OMC" < "$src" > "$T/u.bin"
  { cat "$src"; printf '\0'; printf '%08d' "$(wc -c < "$T/u.bin")"; cat "$T/u.bin"; } >> "$T/units.in"
  echo "omega-ident 1 unit=$name abi=1 profile=OM-1 src=$(sha256sum < "$src" | cut -c1-64) omc=$OMC_PIN path=$u" >> "$T/cudapp_om_units.ident"
done
"$T/native" c < "$T/units.in" > "$T/cudapp_om_units.c"
"$T/native" h < "$T/units.in" > "$T/cudapp_native.h"
if [ "${1:-}" = --check ]; then
  bad=0
  for f in $OUTS; do cmp -s "$T/$f" "$DEST/$f" || { echo "FAIL src/$f differs from the pinned tools' output"; bad=1; }; done
  [ $bad = 0 ] || exit 1
  echo "PASS src/{$(echo $OUTS | tr ' ' ,)} regenerate byte for byte"; exit 0
fi
for f in $OUTS; do cp "$T/$f" "$DEST/$f"; done; echo "wrote $DEST/{$(echo $OUTS | tr ' ' ,)}"
